1	package com.example.starter.blind.repo;
2	
3	import org.springframework.jdbc.core.RowMapper;
4	import org.springframework.jdbc.core.JdbcTemplate;
5	import org.springframework.stereotype.Repository;
6	
7	import java.util.List;
8	
9	/**
10	 * 揭盲申请数据访问；同一分配至多一个待审申请由唯一列 pending_allocation_id 保证。
11	 */
12	@Repository
13	public class UnblindRequestRepository {
14	
15	    /** 揭盲申请行。treatment 为盲底，仅批准后允许返回给申请人。 */
16	    public record UnblindRequestRow(
17	            String id,
18	            String experimentId,
19	            String participantId,
20	            long allocationId,
21	            String reason,
22	            String applicantActor,
23	            String reviewerActor,
24	            String status,
25	            String treatment,
26	            long createdAt,
27	            Long reviewedAt) {
28	    }
29	
30	    private static final RowMapper<UnblindRequestRow> MAPPER = (rs, n) -> new UnblindRequestRow(
31	            rs.getString("id"),
32	            rs.getString("experiment_id"),
33	            rs.getString("participant_id"),
34	            rs.getLong("allocation_id"),
35	            rs.getString("reason"),
36	            rs.getString("applicant_actor"),
37	            rs.getString("reviewer_actor"),
38	            rs.getString("status"),
39	            rs.getString("treatment"),
40	            rs.getLong("created_at"),
41	            (Long) rs.getObject("reviewed_at"));
42	
43	    private static final String COLUMNS =
44	            "id, experiment_id, participant_id, allocation_id, reason, applicant_actor, "
45	                    + "reviewer_actor, status, treatment, created_at, reviewed_at";
46	
47	    private final JdbcTemplate jdbc;
48	
49	    public UnblindRequestRepository(JdbcTemplate jdbc) {
50	        this.jdbc = jdbc;
51	    }
52	
53	    /**
54	     * 插入待审申请；若该分配已有待审申请，唯一索引 uq_unblind_pending 触发异常。
55	     */
56	    public void insertPending(UnblindRequestRow row) {
57	        jdbc.update("INSERT INTO unblind_request ("
58	                        + "id, experiment_id, participant_id, allocation_id, reason, applicant_actor, "
59	                        + "reviewer_actor, status, treatment, created_at, reviewed_at, pending_allocation_id"
60	                        + ") VALUES (?, ?, ?, ?, ?, ?, NULL, 'PENDING', NULL, ?, NULL, ?)",
61	                row.id(), row.experimentId(), row.participantId(), row.allocationId(),
62	                row.reason(), row.applicantActor(), row.createdAt(), row.allocationId());
63	    }
64	
65	    public UnblindRequestRow findById(String requestId) {
66	        List<UnblindRequestRow> rows = jdbc.query(
67	                "SELECT " + COLUMNS + " FROM unblind_request WHERE id = ?", MAPPER, requestId);
68	        return rows.isEmpty() ? null : rows.get(0);
69	    }
70	
71	    /**
72	     * 行级锁定申请，保证批准并发安全。
73	     */
74	    public UnblindRequestRow lockById(String requestId) {
75	        List<UnblindRequestRow> rows = jdbc.query(
76	                "SELECT " + COLUMNS + " FROM unblind_request WHERE id = ? FOR UPDATE",
77	                MAPPER, requestId);
78	        return rows.isEmpty() ? null : rows.get(0);
79	    }
80	
81	    public UnblindRequestRow findPendingByAllocation(long allocationId) {
82	        List<UnblindRequestRow> rows = jdbc.query(
83	                "SELECT " + COLUMNS + " FROM unblind_request "
84	                        + "WHERE pending_allocation_id = ? AND status = 'PENDING'",
85	                MAPPER, allocationId);
86	        return rows.isEmpty() ? null : rows.get(0);
87	    }
88	
89	    /**
90	     * 批准：仅 PENDING 可批准，写入处理代码、批准人与时间，并释放待审唯一占位。
91	     *
92	     * @return 受影响行数；0 表示不存在或已批准
93	     */
94	    public int approve(String requestId, String reviewerActor, String treatment, long reviewedAt) {
95	        return jdbc.update("UPDATE unblind_request SET status = 'APPROVED', reviewer_actor = ?, "
96	                        + "treatment = ?, reviewed_at = ?, pending_allocation_id = NULL "
97	                        + "WHERE id = ? AND status = 'PENDING'",
98	                reviewerActor, treatment, reviewedAt, requestId);
99	    }
100	}
