}

/** 第二阶段结束并完成（仅 COORDINATOR）。 */
@PostMapping("/experiments/{experimentId}/participants/{participantId}/phases/second/end")
public ResponseEntity<String> endSecondPhase(
        @PathVariable String experimentId,
