/** 阶段状态与历史查询（两种角色均可）：只含盲码、状态与时刻，不含处理代码。 */
@GetMapping("/experiments/{experimentId}/participants/{participantId}/phases")
public PhaseView getPhases(@PathVariable String experimentId,
                           @PathVariable String participantId) {
